function run(cpf, hasPunctuation){
    const checkInvalid = function(digits) {
        return !digits.every(value => value === digits[0])
    }

    const digitValidation = function(digits, validating) {
        const digitRange = validating + 8
        const verifArr = validating === 2 ? [11, 10, 9, 8, 7, 6, 5, 4, 3, 2] : [10, 9, 8, 7, 6, 5, 4, 3, 2]
        const digitSum = digits.slice(0, digitRange).map((value, index) => value * verifArr[index]).reduce((acc, cur) => acc + cur)
        const result = (digitSum * 10) % 11
        return result >= 10 ? digits[digitRange] === 0 : digits[digitRange] === result
    }

    const validate = function(cpfString) {
        const digits = String(cpfString).replace(/[\s.-]/g, '').split('').map(val => Number(val))
        const error = !(digits.length === 11) ? true :
            !(checkInvalid(digits)) ? true :
            !(digitValidation(digits, 1)) ? true :
            !(digitValidation(digits, 2)) ? true :
            false

        return !error
    }

    let cpfValido = validate(cpf)

    if(cpfValido){
        if(hasPunctuation){
            cpf = String(cpf).replace(/[\s.-]/g, '')
            cpf = cpf.slice(0, 3) + '.' + cpf.slice(3, 6) + '.' + cpf.slice(6, 9) + '-' + cpf.slice(9)
            return cpf
        } else {
            return cpf.replace(/[^\w]/g, '')
        }
    }

    return false
}

