function applyMask(name) {
	try {

		const nameParts = name.split(" ")
		if (nameParts.length === 1) {
			return nameParts[0];
		}

		const firstName = nameParts[0];
		const rest = name.substring(firstName.length);

		const maskedPart = rest.slice(0, -4).replace(/\S/g, "*");
		const lastFour = rest.slice(-4);

		return `${firstName}${maskedPart}${lastFour}`;

	} catch (error) {
		return name;
	}
}

