  try{
    saturday = processString(saturday)
    sunday = processString(sunday)
    monFri = processString(monFri)

    let data = new Date()
    const offset = (data.getTimezoneOffset() + dateTimeOffset * 60) * 60000    
    let today = data.getTime()
    today = new Date(today + offset)
    const dayOfWeek = today.getDay()

    if(dayOfWeek === 0 && !sunday){
      return false  // Domingos
    } 
    const isSaturday = dayOfWeek === 6  // Sábados
    const isSunday = dayOfWeek === 0  // Domingos

    const hour = today.getHours()
    const minutes = today.getMinutes()
    const time = hour * 60 + minutes


    const days = [monFri, saturday, sunday]
    const index = isSaturday ? 1 : (isSunday ? 2 : 0)
    const arr = days[index]
    const size = arr.length

    if(isNaN(arr[0])) return false  // String vazia
    if(size % 2 === 1) return 'error'  // Um início de expediente tem que ser seguido de seu fim.

    for(let i = 0; i < size; i+=2){
      if(arr[i] <= time && time < arr[i + 1]) return true
